sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.cfs-footer {
  background: #111827;

  color: white;

  padding-top: 50px;
}

.footer-container {
  max-width: 1200px;

  margin: auto;

  padding: 0 20px 45px;

  display: grid;

  grid-template-columns:
    2fr 1fr 1fr;

  gap: 50px;
}

.footer-brand h3 {
  font-size: 20px;
}

.footer-brand p {
  margin-top: 12px;

  max-width: 350px;

  color: #9ca3af;

  line-height: 1.6;
}

.footer-column {
  display: flex;

  flex-direction: column;

  gap: 12px;
}

.footer-column h4 {
  margin-bottom: 5px;
}

.footer-column a {
  color: #9ca3af;

  text-decoration: none;

  font-size: 14px;
}

.footer-column a:hover {
  color: white;
}

.footer-bottom {
  border-top: 1px solid #374151;

  padding: 20px;

  max-width: 1200px;

  margin: auto;

  display: flex;

  justify-content: space-between;

  color: #9ca3af;

  font-size: 12px;
}

@media(max-width: 700px) {

  .footer-container {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 8px;
  }

}
